const body=$json.body ?? {};
const clean=v=>String(v??'').trim();
const orderId=clean(body.orderId)||'unknown';
const reject=reason=>[{json:{status:'rejected',reason,orderId}}];
const email=clean(body.customer?.email).toLowerCase();
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return reject('invalid_email');
const items=body.items;
if(!Array.isArray(items)||!items.length||items.length>100)return reject('invalid_items');
let totalCents=0;
for(const item of items){
  if(typeof item?.price!=='number'||!Number.isFinite(item.price)||item.price<0||item.price>1e12||typeof item?.qty!=='number'||!Number.isSafeInteger(item.qty)||item.qty<1||item.qty>10000)return reject('invalid_items');
  // Decimal input policy: at most two fractional digits in canonical number text.
  if(!/^\d+(?:\.\d{1,2})?$/.test(String(item.price)))return reject('invalid_items');
  const [whole,fraction='']=String(item.price).split('.');
  const cents=Number(whole)*100+Number(fraction.padEnd(2,'0'));
  const lineCents=cents*item.qty;
  if(!Number.isSafeInteger(cents)||!Number.isSafeInteger(lineCents)||!Number.isSafeInteger(totalCents+lineCents))return reject('invalid_items');
  totalCents+=lineCents;
}
return [{json:{status:'accepted',orderId,email,itemCount:items.length,totalCents,total:totalCents/100,currency:'EUR'}}];
